package com.example.starter.epidemic.domain;

/**
 * 报告卡生命周期状态。
 *
 * <p>流转：初报后 {@link #PENDING_REVIEW}（待审核）→ 审核通过 {@link #PENDING_FINAL}（待终审）
 * → 终审归档 {@link #ARCHIVED}（只读终态）；审核通过前可撤回为 {@link #WITHDRAWN}（终态）。
 * 病种变更类订正会把卡片从 {@link #PENDING_FINAL} 重置回 {@link #PENDING_REVIEW}。</p>
 */
public enum CardStatus {
    /** 待初审：初报提交后、或病种变更类订正后所处状态。 */
    PENDING_REVIEW,
    /** 待终审：初审通过、尚未归档；非病种变更订正不改变该状态。 */
    PENDING_FINAL,
    /** 已归档（终审）：只读终态，仅允许双人“特殊订正”。 */
    ARCHIVED,
    /** 已撤回：审核通过前撤回，终态不可恢复。 */
    WITHDRAWN
}

package com.example.starter.epidemic.domain;

/**
 * 传染病病种分类及报告时限。
 *
 * <p>报告时限自诊断时刻（UTC）起算：甲类 {@code A} 为 2 小时，乙类 {@code B} 为 24 小时；
 * 恰在时限终点提交判为及时。</p>
 */
public enum DiseaseCategory {
    /** 甲类传染病，报告时限 2 小时。 */
    A(2),
    /** 乙类传染病，报告时限 24 小时。 */
    B(24);

    private final int deadlineHours;

    DiseaseCategory(int deadlineHours) {
        this.deadlineHours = deadlineHours;
    }

    /** 报告时限（小时）。 */
    public int deadlineHours() {
        return deadlineHours;
    }
}

package com.example.starter.epidemic.domain;

/**
 * 审核轨迹动作类型，覆盖提交、审核、撤回、归档及特殊订正全过程，保证轨迹可复算。
 */
public enum AuditAction {
    /** 初报提交。 */
    SUBMIT,
    /** 初审通过。 */
    REVIEW_APPROVED,
    /** 病种变更类订正导致原初审结论作废。 */
    REVIEW_VOIDED,
    /** 审核通过前撤回。 */
    WITHDRAWN,
    /** 终审归档。 */
    ARCHIVED,
    /** 归档后发起特殊订正。 */
    SPECIAL_STARTED,
    /** 特殊订正第一名审核员确认。 */
    SPECIAL_FIRST_CONFIRMED,
    /** 特殊订正第二名审核员确认并生效。 */
    SPECIAL_SECOND_CONFIRMED,
    /** 订正提交（非病种变更）。 */
    CORRECTED
}

package com.example.starter.epidemic.domain;

/**
 * 归档后特殊订正的确认状态：须两名不同审核员先后确认。
 */
public enum SpecialStatus {
    /** 已发起、等待第二名（不同）审核员确认；单人确认时卡片数据不变更。 */
    WAITING_SECOND,
    /** 两名不同审核员均已确认，订正生效。 */
    EFFECTIVE
}

