package com.example.starter.epidemic.domain;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 报告卡主表行模型：一张有效卡对应一行，随最新版本与终态更新。
 *
 * <p>{@code dedupKey} 为“患者＋病种＋发病日期”去重指纹，有效卡唯一；撤回终态时置空
 * （唯一索引允许多个 NULL），从而由数据库保证并发重复报告只有一张有效卡。</p>
 */
public class CardPo {
    /** 卡片编号，业务主键，全局唯一。 */
    private String cardNo;
    /** 患者证件号（合成数据），去重维度之一。 */
    private String patientId;
    /** 患者姓名。 */
    private String patientName;
    /** 当前病种编码，去重维度之一。 */
    private String diseaseCode;
    /** 发病日期（无时区日期，UTC 口径记录），去重维度之一。 */
    private LocalDate onsetDate;
    /** 报告医疗机构编码。 */
    private String institutionCode;
    /** 当前最新版本号，初报为 1。 */
    private int currentVersion;
    /** 卡片状态。 */
    private CardStatus status;
    /** 有效卡去重指纹；撤回后为 null。 */
    private String dedupKey;
    /** 创建时刻（UTC）。 */
    private Instant createdAt;
    /** 最近更新时刻（UTC）。 */
    private Instant updatedAt;

    public String getCardNo() { return cardNo; }
    public void setCardNo(String cardNo) { this.cardNo = cardNo; }
    public String getPatientId() { return patientId; }
    public void setPatientId(String patientId) { this.patientId = patientId; }
    public String getPatientName() { return patientName; }
    public void setPatientName(String patientName) { this.patientName = patientName; }
    public String getDiseaseCode() { return diseaseCode; }
    public void setDiseaseCode(String diseaseCode) { this.diseaseCode = diseaseCode; }
    public LocalDate getOnsetDate() { return onsetDate; }
    public void setOnsetDate(LocalDate onsetDate) { this.onsetDate = onsetDate; }
    public String getInstitutionCode() { return institutionCode; }
    public void setInstitutionCode(String institutionCode) { this.institutionCode = institutionCode; }
    public int getCurrentVersion() { return currentVersion; }
    public void setCurrentVersion(int currentVersion) { this.currentVersion = currentVersion; }
    public CardStatus getStatus() { return status; }
    public void setStatus(CardStatus status) { this.status = status; }
    public String getDedupKey() { return dedupKey; }
    public void setDedupKey(String dedupKey) { this.dedupKey = dedupKey; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(Instant updatedAt) { this.updatedAt = updatedAt; }
}

package com.example.starter.epidemic.domain;

import java.time.Instant;

/**
 * 审核轨迹行（不可变）：提交、审核、作废、撤回、归档、特殊订正确认均留痕，支持复算。
 *
 * @param id        自增主键
 * @param cardNo    卡片编号
 * @param versionNo 轨迹发生时的版本号
 * @param action    动作类型
 * @param operator  操作人（审核员/报告人/系统）
 * @param detail    动作说明（如作废的原审核结论）
 * @param createdAt 发生时刻（UTC）
 */
public record AuditTrailPo(
        Long id,
        String cardNo,
        int versionNo,
        AuditAction action,
        String operator,
        String detail,
        Instant createdAt
) {
}

package com.example.starter.epidemic.domain;

/**
 * 病种目录行（合成数据）。
 *
 * @param code     病种编码，业务主键
 * @param name     病种名称
 * @param category 病种分类，决定报告时限
 */
public record DiseasePo(String code, String name, DiseaseCategory category) {
}

package com.example.starter.epidemic.domain;

/**
 * 医疗机构目录行（合成数据）。
 *
 * @param code 机构编码，业务主键
 * @param name 机构名称
 */
public record InstitutionPo(String code, String name) {
}

package com.example.starter.epidemic.domain;

import java.time.Instant;

/**
 * 归档后“特殊订正”流程行：须两名不同审核员先后确认方才生效，单人确认期间数据不变更。
 */
public class SpecialCorrectionPo {
    /** 自增主键。 */
    private Long id;
    /** 卡片编号。 */
    private String cardNo;
    /** 发起特殊订正的幂等键。 */
    private String requestId;
    /** 订正后病种编码。 */
    private String diseaseCode;
    /** 订正后病例类型：SUSPECTED 疑似 / CONFIRMED 确诊。 */
    private String caseType;
    /** 订正后诊断时刻（UTC）。 */
    private Instant diagnosisTime;
    /** 订正说明（疫情核实结论）。 */
    private String reason;
    /** 发起人。 */
    private String initiator;
    /** 第一名审核员。 */
    private String firstReviewer;
    /** 第一名确认时刻（UTC）。 */
    private Instant firstAt;
    /** 第二名审核员（必须与第一人不同）。 */
    private String secondReviewer;
    /** 第二名确认并生效时刻（UTC）。 */
    private Instant secondAt;
    /** 流程状态。 */
    private SpecialStatus status;
    /** 生效后生成的新版本号；未生效为 null。 */
    private Integer effectiveVersion;
    /** 创建时刻（UTC）。 */
    private Instant createdAt;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getCardNo() { return cardNo; }
    public void setCardNo(String cardNo) { this.cardNo = cardNo; }
    public String getRequestId() { return requestId; }
    public void setRequestId(String requestId) { this.requestId = requestId; }
    public String getDiseaseCode() { return diseaseCode; }
    public void setDiseaseCode(String diseaseCode) { this.diseaseCode = diseaseCode; }
    public String getCaseType() { return caseType; }
    public void setCaseType(String caseType) { this.caseType = caseType; }
    public Instant getDiagnosisTime() { return diagnosisTime; }
    public void setDiagnosisTime(Instant diagnosisTime) { this.diagnosisTime = diagnosisTime; }
    public String getReason() { return reason; }
    public void setReason(String reason) { this.reason = reason; }
    public String getInitiator() { return initiator; }
    public void setInitiator(String initiator) { this.initiator = initiator; }
    public String getFirstReviewer() { return firstReviewer; }
    public void setFirstReviewer(String firstReviewer) { this.firstReviewer = firstReviewer; }
    public Instant getFirstAt() { return firstAt; }
    public void setFirstAt(Instant firstAt) { this.firstAt = firstAt; }
    public String getSecondReviewer() { return secondReviewer; }
    public void setSecondReviewer(String secondReviewer) { this.secondReviewer = secondReviewer; }
    public Instant getSecondAt() { return secondAt; }
    public void setSecondAt(Instant secondAt) { this.secondAt = secondAt; }
    public SpecialStatus getStatus() { return status; }
    public void setStatus(SpecialStatus status) { this.status = status; }
    public Integer getEffectiveVersion() { return effectiveVersion; }
    public void setEffectiveVersion(Integer effectiveVersion) { this.effectiveVersion = effectiveVersion; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
}

package com.example.starter.epidemic.domain;

import java.time.Instant;

/**
 * 幂等记录行：指纹覆盖 requestId 与全部业务字段。
 *
 * @param requestId    幂等键（初报/订正/特殊订正发起）
 * @param scope        场景：SUBMIT 初报 / CORRECTION 订正 / SPECIAL 特殊订正
 * @param fingerprint   请求参数指纹（含 requestId）
 * @param cardNo       首次成功请求关联的卡片编号
 * @param versionNo    首次成功请求产生的版本号（特殊订正发起时为发起时版本）
 * @param responseJson 首次成功响应快照，重放原样返回
 * @param createdAt    首次请求时刻（UTC）
 */
public record IdempotencyPo(
        String requestId,
        String scope,
        String fingerprint,
        String cardNo,
        Integer versionNo,
        String responseJson,
        Instant createdAt
) {
}

