package com.example.starter.epidemic;

import com.example.starter.epidemic.api.CardResponse;
import com.example.starter.epidemic.api.ReviewRequest;
import com.example.starter.epidemic.api.SubmitCardRequest;
import com.example.starter.epidemic.api.WithdrawRequest;
import com.example.starter.epidemic.domain.CardStatus;
import com.example.starter.epidemic.service.ApiException;
import com.example.starter.epidemic.service.EpidemicCardService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;

import java.time.Instant;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * H2 真实并发测试：初审通过与撤回并发时必须形成唯一终态；并发重复报告由唯一约束裁决只建一张卡。
 */
class ConcurrencyTest extends AbstractIntegrationTest {

    @Autowired
    private EpidemicCardService service;

    @Test
    void concurrentReviewAndWithdraft_singleTerminalState() throws Exception {
        CardResponse card = service.submit(submitRequest("req-race-init", "P-RACE", "B02",
                BASE_TIME.minusSeconds(3600)));

        ExecutorService pool = Executors.newFixedThreadPool(2);
        try {
            CyclicBarrier barrier = new CyclicBarrier(2);

            Future<CardStatus> reviewFuture = pool.submit(() -> {
                barrier.await(10, TimeUnit.SECONDS);
                service.review(card.cardNo(), new ReviewRequest("auditor-01", "并发初审"));
                return CardStatus.PENDING_FINAL;
            });
            Future<CardStatus> withdrawFuture = pool.submit(() -> {
                barrier.await(10, TimeUnit.SECONDS);
                service.withdraw(card.cardNo(), new WithdrawRequest("reporter-1", "并发撤回"));
                return CardStatus.WITHDRAWN;
            });

            CardStatus winner;
            CardStatus loser;
            try {
                winner = reviewFuture.get(15, TimeUnit.SECONDS);
                loser = assertThrowsApi(withdrawFuture);
            } catch (ExecutionException reviewFailed) {
                winner = withdrawFuture.get(15, TimeUnit.SECONDS);
                loser = assertApiException(reviewFailed);
            }

            assertTrue(winner == CardStatus.PENDING_FINAL || winner == CardStatus.WITHDRAWN);
            assertTrue(loser == CardStatus.PENDING_FINAL || loser == CardStatus.WITHDRAWN);
            assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM card", Integer.class));

            CardStatus finalState = service.getCard(card.cardNo()).status();
            assertEquals(winner, finalState, "数据库终态必须与胜出动作一致，只允许一个终态");
            assertTrue(finalState == CardStatus.PENDING_FINAL || finalState == CardStatus.WITHDRAWN);
        } finally {
            pool.shutdownNow();
        }
    }

    @Test
    void concurrentDuplicateSubmissions_onlyOneCardCreated() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        try {
            CyclicBarrier barrier = new CyclicBarrier(2);

            java.util.List<Future<CardResponse>> futures = new java.util.ArrayList<>();
            for (int i = 0; i < 2; i++) {
                int idx = i;
                futures.add(pool.submit(() -> {
                    SubmitCardRequest req = submitRequest("req-dup-conc-" + idx, "P-DUP-CONC",
                            "B02", BASE_TIME.minusSeconds(1800));
                    barrier.await(10, TimeUnit.SECONDS);
                    return service.submit(req);
                }));
            }

            CardResponse r1 = futures.get(0).get(15, TimeUnit.SECONDS);
            CardResponse r2 = futures.get(1).get(15, TimeUnit.SECONDS);
            assertEquals(r1.cardNo(), r2.cardNo(), "并发重复报告必须指向同一张卡");
            assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM card", Integer.class),
                    "唯一约束须保证只有一张有效卡");
            assertEquals(1, jdbc.queryForObject(
                    "SELECT COUNT(*) FROM card_version WHERE card_no = ?", Integer.class,
                    r1.cardNo()));
        } finally {
            pool.shutdownNow();
        }
    }

    private CardStatus assertThrowsApi(Future<CardStatus> future) throws Exception {
        try {
            CardStatus status = future.get(15, TimeUnit.SECONDS);
            throw new AssertionError("预期落败动作抛异常，但返回了 " + status);
        } catch (ExecutionException e) {
            return assertApiException(e);
        }
    }

    private CardStatus assertApiException(ExecutionException e) {
        Throwable cause = e.getCause();
        assertTrue(cause instanceof ApiException, "落败动作须为业务异常，实际: " + cause);
        // 落败方意图状态与胜出方相反，仅用于断言两者不同；终态以库中状态为准。
        return cause.getMessage().contains("撤回") ? CardStatus.WITHDRAWN : CardStatus.PENDING_FINAL;
    }
}

